css:
/* Page Setup for Landscape */
@page {
    size: A4 landscape;
    margin: 10mm;
}

@media print {
    @page {
        size: A4 landscape;
        margin: 10mm;
    }

    body {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, sans-serif;
    font-size: 10px;
    line-height: 1.3;
    color: #000;
}

.container {
    width: 100%;
    padding: 10px;
}

/* Header Section - FIXED */
.invoice-header {
    position: relative;
    width: 100%;
    margin-bottom: 15px;
    min-height: 80px;
}

.company-info {
    float: left;
    width: 30%;
    font-size: 9px;
    line-height: 1.4;
}

.company-info img {
    height: 50px;
    margin-bottom: 5px;
}

.invoice-title-box {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
}

.invoice-title {
    border: 2px solid #000;
    padding: 10px 30px;
    font-size: 18px;
    font-weight: bold;
    display: inline-block;
    white-space: nowrap;
}

.page-info {
    float: right;
    width: 30%;
    text-align: right;
    font-size: 9px;
}

/* Shipping Section - FIXED */
.shipping-section {
    display: table;
    width: 100%;
    margin-bottom: 10px;
    clear: both;
}

.ship-to-box {
    display: table-cell;
    width: 25%;
    vertical-align: top;
    font-size: 9px;
    padding-right: 10px;
}

.section-title {
    font-weight: bold;
    margin-bottom: 3px;
}

.freight-box {
    display: table-cell;
    width: 25%;
    vertical-align: top;
    font-size: 9px;
    padding-right: 10px;
    text-align: center;
    margin-right: -162px;
}

.freight-box .section-title {
    text-align: center;
    margin-right: -162px;
}

.invoice-details-box {
    display: table-cell;
    width: 50%;
    vertical-align: top;
    font-size: 9px;
    text-align: right;
}

.detail-line {
    margin: 2px 0;
}

/* Items Table */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin: 10px 0;
    font-size: 8px;
}

.items-table th,
.items-table td {
    border: 1px solid #000;
    padding: 4px 3px;
    vertical-align: top;
}

.items-table th {
    background-color: #f5f5f5;
    font-weight: bold;
    text-align: center;
    font-size: 8px;
    line-height: 1.2;
}

/* Column Widths */
.items-table th:nth-child(1),
.items-table td:nth-child(1) { width: 8%; }

.items-table th:nth-child(2),
.items-table td:nth-child(2) { width: 20%; }

.items-table th:nth-child(3),
.items-table td:nth-child(3) { width: 6%; }

.items-table th:nth-child(4),
.items-table td:nth-child(4) { width: 5%; }

.items-table th:nth-child(5),
.items-table td:nth-child(5) { width: 9%; }

.items-table th:nth-child(6),
.items-table td:nth-child(6) { width: 5%; }

.items-table th:nth-child(7),
.items-table td:nth-child(7) { width: 6%; }

.items-table th:nth-child(8),
.items-table td:nth-child(8) { width: 5%; }

.items-table th:nth-child(9),
.items-table td:nth-child(9) { width: 6%; }

.items-table th:nth-child(10),
.items-table td:nth-child(10) { width: 5%; }

.items-table th:nth-child(11),
.items-table td:nth-child(11) { width: 8%; }

.items-table th:nth-child(12),
.items-table td:nth-child(12) { width: 10%; }

/* Text Alignment */
.text-left {
    text-align: left !important;
}

.text-center {
    text-align: center !important;
}

.text-right {
    text-align: right !important;
}

/* Default Column Alignments */
.items-table tbody td:nth-child(1),
.items-table tbody td:nth-child(2) {
    text-align: left;
}

.items-table tbody td:nth-child(3),
.items-table tbody td:nth-child(4),
.items-table tbody td:nth-child(5),
.items-table tbody td:nth-child(6),
.items-table tbody td:nth-child(8),
.items-table tbody td:nth-child(9),
.items-table tbody td:nth-child(10) {
    text-align: center;
}

.items-table tbody td:nth-child(7),
.items-table tbody td:nth-child(11),
.items-table tbody td:nth-child(12) {
    text-align: right;
}

/* Summary Section */
.summary-section {
    display: table;
    width: 100%;
    margin-top: 15px;
    font-size: 9px;
}

.summary-left {
    display: table-cell;
    width: 50%;
    vertical-align: top;
}

.summary-right {
    display: table-cell;
    width: 50%;
    vertical-align: top;
    text-align: right;
}

.summary-line {
    margin: 3px 0;
}

/* Footer */
.footer-notes {
    margin-top: 15px;
    font-size: 8px;
    line-height: 1.4;
    border-top: 1px solid #ccc;
    padding-top: 10px;
}

.stamp-section {
    margin-top: 20px;
    text-align: right;
}

.stamp-section img {
    height: 60px;
}

.signature-line {
    margin-top: 10px;
}

.clearfix::after {
    content: "";
    display: table;
    clear: both;
}
